#!/usr/bin/env python3
"""Vikas Furnished - Site builder. Concatenates CSS parts and generates pages."""
import json, os, html, base64

DATA = json.load(open('site_data.json'))
SITE = DATA['site']

def fmt(a): return '\u20b9' + f'{a:,}'
def e(s): return html.escape(str(s))
def ph_img(name,w=600,h=400):
    d=name.replace('-',' ').title()
    svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}"><rect width="{w}" height="{h}" fill="#f5f0eb"/><circle cx="{w//2}" cy="{int(h*0.38)}" r="36" fill="#8b7355" opacity="0.12"/><text x="50%" y="92%" text-anchor="middle" font-family="Georgia" font-size="13" fill="#9a8c7a" opacity="0.6">{e(d)}</text></svg>'
    return 'data:image/svg+xml;base64,'+base64.b64encode(svg.encode()).decode()
def stars(r):
    f=int(r);h=(r-f)>=0.5;s='<div class="stars">'
    for i in range(1,6):
        if i<=f:s+='<span class="star star-full">\u2605</span>'
        elif h and i==f+1:s+='<span class="star star-half">\u2605</span>'
        else:s+='<span class="star star-empty">\u2605</span>'
    return s+'</div>'

CSS = open('assets/css/style.part1.css').read()
os.makedirs('assets/css',exist_ok=True)
os.makedirs('products',exist_ok=True)
with open('assets/css/style.css','w') as f: f.write(CSS)

def header(pt,md,active=''):
    return f'''<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{e(md)}"><title>{e(pt)}</title><link rel="icon" href="data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><rect width='100' height='100' rx='18' fill='%23262220'/><text x='50' y='68' font-size='52' font-family='Georgia' font-weight='bold' fill='%23c9a87c' text-anchor='middle'>V</text></svg>"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500;600;700&family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/style.css"></head><body><div class="top-bar"><div class="container"><p>\u2726 Free delivery & installation on orders above \u20b950,000 across India \u2726</p></div></div><header class="site-header" id="siteHeader"><div class="container header-inner"><button class="menu-toggle" id="menuToggle" aria-label="Toggle menu" aria-expanded="false"><span></span><span></span><span></span></button><a href="index.html" class="logo"><span class="logo-mark">V</span><span class="logo-text"><span class="logo-name">Vikas Furnished</span><span class="logo-tagline">Crafting Comfort</span></span></a><nav class="main-nav" id="mainNav"><ul><li><a href="index.html" class="{'active' if active=='home' else ''}">Home</a></li><li><a href="products.html" class="{'active' if active=='products' else ''}">Products</a></li><li><a href="about.html" class="{'active' if active=='about' else ''}">About</a></li><li><a href="contact.html" class="{'active' if active=='contact' else ''}">Contact</a></li></ul></nav><div class="header-actions"><a href="contact.html" class="btn btn-outline btn-sm">Get in Touch</a></div></div></header>'''

def footer():
    cl=''.join(f'<li><a href="products.html?category={e(c["slug"])}">{e(c["name"])}</a></li>' for c in DATA['categories'])
    import datetime
    return f'<section class="newsletter"><div class="container"><div class="newsletter-inner"><div class="newsletter-text"><h2>Join the Vikas Furnished Family</h2><p>Subscribe for exclusive offers.</p></div><form class="newsletter-form"><input type="email" placeholder="Your email" required><button type="submit" class="btn btn-primary">Subscribe</button></form></div></div></section><footer class="site-footer"><div class="container"><div class="footer-grid"><div class="footer-col footer-brand"><a href="index.html" class="logo logo-footer"><span class="logo-mark">V</span><span class="logo-text"><span class="logo-name">Vikas Furnished</span><span class="logo-tagline">Crafting Comfort</span></span></a><p class="footer-about">Premium handcrafted furniture for modern Indian homes.</p><div class="social-links"><a href="#">FB</a><a href="#">IG</a><a href="#">PIN</a><a href="#">YT</a></div></div><div class="footer-col"><h3>Shop</h3><ul class="footer-links">{cl}</ul></div><div class="footer-col"><h3>Company</h3><ul class="footer-links"><li><a href="about.html">About</a></li><li><a href="products.html">Products</a></li><li><a href="contact.html">Contact</a></li><li><a href="privacy.html">Privacy</a></li><li><a href="terms.html">Terms</a></li></ul></div><div class="footer-col"><h3>Get in Touch</h3><ul class="footer-contact"><li><strong>Address:</strong><br>{e(SITE["address"])}</li><li><strong>Phone:</strong><br><a href="tel:+919876543210">{e(SITE["phone"])}</a></li><li><strong>Email:</strong><br><a href="mailto:{e(SITE["email"])}">{e(SITE["email"])}</a></li></ul></div></div><div class="footer-bottom"><p>\u00a9 {datetime.datetime.now().year} Vikas Furnished. All rights reserved.</p></div></div></footer><button class="back-to-top" id="backToTop"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><path d="M12 19V5M5 12l7-7 7 7"/></svg></button><script src="assets/js/main.js"></script></body></html>'

def pcard(p):
    bm={'Bestseller':'badge-bestseller','New':'badge-new','Sale':'badge-sale','Premium':'badge-premium'}
    bc=bm.get(p.get('badge',''),'badge-default')
    bh=f'<span class="badge {bc}">{e(p["badge"])}</span>' if p.get('badge') else ''
    dh=''
    if p.get('old_price') and p['old_price']>p['price']:
        pct=round((1-p['price']/p['old_price'])*100)
        dh=f'<span class="price-old">{fmt(p["old_price"])}</span><span class="price-discount">{pct}% off</span>'
    return f'<article class="product-card"><a href="products/{p["slug"]}.html" class="product-card-link"><div class="product-image">{bh}<img src="{ph_img(p["image"])}" alt="{e(p["name"])}" loading="lazy"><div class="product-image-overlay"><span class="view-details">View Details \u2192</span></div></div><div class="product-info"><span class="product-category">{e(p["category_name"])}</span><h3 class="product-name">{e(p["name"])}</h3><div class="product-rating">{stars(p["rating"])}<span class="review-count">({p["reviews"]})</span></div><div class="product-price"><span class="price-current">{fmt(p["price"])}</span>{dh}</div></div></a></article>'

# Generate index.html
featured=[p for p in DATA['products'] if p.get('badge') in('Bestseller','Premium','New')][:8]
cg=''.join(f'<a href="products.html?category={e(c["slug"])}" class="category-card reveal reveal-delay-{(i%4)+1}"><div class="category-icon">{c["icon"]}</div><h3>{e(c["name"])}</h3><p>{e(c["description"])}</p><span class="view-link">Shop Now \u2192</span></a>' for i,c in enumerate(DATA['categories']))
pg=''.join(f'<div class="reveal reveal-delay-{(i%4)+1}">{pcard(p)}</div>' for i,p in enumerate(featured))
tg=''.join(f'<div class="testimonial-card reveal reveal-delay-{(i%3)+1}"><div class="testimonial-quote-mark">"</div><p class="testimonial-text">{e(t["text"])}</p><div class="testimonial-author"><div class="testimonial-avatar">{e(t["name"][0])}</div><div><div class="testimonial-name">{e(t["name"])}</div><div class="testimonial-location">{e(t["location"])}</div></div></div></div>' for i,t in enumerate(DATA['testimonials']))
with open('index.html','w') as f:
    f.write(header(f'{SITE["name"]} \u2014 {SITE["tagline"]}','Premium handcrafted furniture for modern Indian homes.','home')+f'<section class="hero"><div class="hero-bg"></div><div class="container"><div class="hero-content"><span class="eyebrow">Premium Handcrafted Furniture</span><h1>Furniture That<br><span class="accent">Defines</span> Your Space</h1><p>Discover thoughtfully designed furniture crafted with premium materials. Bringing comfort, elegance, and lasting quality to homes across India.</p><div class="hero-actions"><a href="products.html" class="btn btn-gold btn-lg">Explore Collection</a><a href="about.html" class="btn btn-outline btn-lg" style="color:#f5f0eb;border-color:rgba(245,240,235,.5)">Our Story</a></div><div class="hero-stats"><div class="hero-stat"><strong>15+</strong><span>Years of Craftsmanship</span></div><div class="hero-stat"><strong>10k+</strong><span>Happy Customers</span></div><div class="hero-stat"><strong>500+</strong><span>Premium Designs</span></div></div></div></div></section><section class="section section-cream"><div class="container"><div class="section-header reveal"><span class="eyebrow">Browse by Category</span><h2 class="section-title">Explore Our Collections</h2><p class="section-subtitle">From statement sofas to elegant dining sets.</p></div><div class="category-grid">{cg}</div></div></section><section class="section"><div class="container"><div class="section-header reveal"><span class="eyebrow">Bestsellers & New Arrivals</span><h2 class="section-title">Featured Products</h2><p class="section-subtitle">Our most-loved pieces.</p></div><div class="product-grid">{pg}</div><div class="text-center" style="margin-top:2.5rem"><a href="products.html" class="btn btn-primary btn-lg">View All Products</a></div></div></section><section class="section section-cream"><div class="container"><div class="about-home"><div class="about-visual reveal"></div><div class="about-content reveal reveal-delay-1"><span class="eyebrow">About Vikas Furnished</span><h2 class="section-title">Crafted with Care, Built to Last</h2><p class="section-subtitle">For over 15 years, Vikas Furnished has been creating premium furniture combining traditional craftsmanship with contemporary design.</p><p style="color:var(--color-text-light);margin-bottom:1.5rem">Every piece tells a story of meticulous attention to detail and sustainably sourced materials.</p><div class="about-features"><div class="about-feature"><div class="about-feature-icon">\U0001fab5</div><div><strong>Solid Wood</strong><p>Premium sheesham & teak</p></div></div><div class="about-feature"><div class="about-feature-icon">\U0001f932</div><div><strong>Handcrafted</strong><p>Skilled artisan work</p></div></div><div class="about-feature"><div class="about-feature-icon">\U0001f69a</div><div><strong>Free Delivery</strong><p>Across India</p></div></div><div class="about-feature"><div class="about-feature-icon">\U0001f6e1\ufe0f</div><div><strong>5-Year Warranty</strong><p>On all frames</p></div></div></div><a href="about.html" class="btn btn-outline" style="margin-top:2rem">Learn More</a></div></div></div></section><section class="section section-dark"><div class="container"><div class="section-header reveal"><span class="eyebrow" style="color:var(--color-gold)">Why Choose Us</span><h2 class="section-title" style="color:var(--color-cream)">The Vikas Furnished Difference</h2><p class="section-subtitle" style="color:var(--color-cream-dark)">Committed to delivering furniture that exceeds expectations.</p></div><div class="features-grid"><div class="feature-block reveal"><div class="feature-icon">\U0001f3a8</div><h3 style="color:var(--color-cream)">Premium Design</h3><p style="color:var(--color-cream-dark)">Thoughtfully designed pieces.</p></div><div class="feature-block reveal reveal-delay-1"><div class="feature-icon">\U0001fab5</div><h3 style="color:var(--color-cream)">Quality Materials</h3><p style="color:var(--color-cream-dark)">Solid wood and premium fabrics.</p></div><div class="feature-block reveal reveal-delay-2"><div class="feature-icon">\U0001f69a</div><h3 style="color:var(--color-cream)">Pan-India Delivery</h3><p style="color:var(--color-cream-dark)">Free delivery above \u20b950,000.</p></div><div class="feature-block reveal reveal-delay-3"><div class="feature-icon">\U0001f6e1\ufe0f</div><h3 style="color:var(--color-cream)">Warranty & Support</h3><p style="color:var(--color-cream-dark)">5-year warranty on frames.</p></div></div></div></section><section class="section"><div class="container"><div class="section-header reveal"><span class="eyebrow">Customer Stories</span><h2 class="section-title">Loved by Thousands</h2></div><div class="testimonials-grid">{tg}</div></div></section><section class="cta-section"><div class="container"><h2>Ready to Transform Your Space?</h2><p>Browse our complete collection. Free delivery across India.</p><a href="products.html" class="btn btn-gold btn-lg">Shop the Collection</a><a href="contact.html" class="btn btn-light btn-lg" style="margin-left:1rem">Talk to a Designer</a></div></section>'+footer())
print('Built index.html')

# Generate products.html
pdata=json.dumps([{'id':p['id'],'name':p['name'],'slug':p['slug'],'category_id':p['category_id'],'category_name':p['category_name'],'price':p['price'],'old_price':p['old_price'],'badge':p['badge'],'rating':p['rating'],'reviews':p['reviews'],'image':p['image']} for p in DATA['products']])
catmap=json.dumps({c['slug']:c['id'] for c in DATA['categories']})
fl=f'<li><a href="products.html" class="active">All Products <span class="count">{len(DATA["products"])}</span></a></li>'
for c in DATA['categories']:
    cnt=len([p for p in DATA['products'] if p['category_id']==c['id']])
    fl+=f'<li><a href="products.html?category={e(c["slug"])}">{c["icon"]} {e(c["name"])} <span class="count">{cnt}</span></a></li>'
pgrid=''.join(f'<div class="reveal reveal-delay-{(i%4)+1}">{pcard(p)}</div>' for i,p in enumerate(DATA['products']))
with open('products.html','w') as f:
    f.write(header('All Products \u2014 Vikas Furnished','Browse premium furniture.','products')+f'<div class="page-banner"><div class="container"><h1>Our Products</h1><p>Explore our complete collection</p><div class="breadcrumb"><a href="index.html">Home</a><span>/</span><a href="products.html">Products</a></div></div></div><div class="container"><div class="products-layout"><aside class="products-sidebar"><div class="sidebar-block"><h3>Categories</h3><ul class="filter-list">{fl}</ul></div><div class="sidebar-block"><h3>Need Help?</h3><p style="font-size:.88rem;color:var(--color-text-light);margin-bottom:1rem">Our experts are here to help.</p><a href="contact.html" class="btn btn-outline btn-sm">Contact Us</a></div></aside><div class="products-main"><div class="products-toolbar"><span class="products-count">Showing {len(DATA["products"])} products</span><select id="sortSelect"><option value="default">Sort: Default</option><option value="price-low">Price: Low to High</option><option value="price-high">Price: High to Low</option><option value="rating">Rating: Highest</option><option value="name">Name: A to Z</option></select></div><div class="product-grid" id="productGrid">{pgrid}</div></div></div></div><script>var VF_PRODUCTS={pdata};var VF_CATMAP={catmap};var p=new URLSearchParams(location.search).get("category");function fP(a){{return"\u20b9"+a.toLocaleString("en-IN")}}function pI(n){{var d=n.replace(/-/g," ").replace(/\b\w/g,c=>c.toUpperCase());var s="<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"600\" height=\"400\"><rect width=\"600\" height=\"400\" fill=\"#f5f0eb\"/><text x=\"50%\" y=\"92%\" text-anchor=\"middle\" font-family=\"Georgia\" font-size=\"13\" fill=\"#9a8c7a\" opacity=\"0.6\">"+d+"</text></svg>";return"data:image/svg+xml;base64,"+btoa(s)}}function st(r){{var f=Math.floor(r),h=(r-f)>=.5,s="";for(var i=1;i<=5;i++){{if(i<=f)s+="<span class=\"star star-full\">\u2605</span>";else if(h&&i==f+1)s+="<span class=\"star star-half\">\u2605</span>";else s+="<span class=\"star star-empty\">\u2605</span>"}}return"<div class=\"stars\">"+s+"</div>"}}function rc(p){{var bm={{"Bestseller":"badge-bestseller","New":"badge-new","Sale":"badge-sale","Premium":"badge-premium"}},bc=bm[p.badge]||"badge-default",bh=p.badge?"<span class=\"badge \"+bc+\">"+p.badge+"</span>":"",dh="";if(p.old_price&&p.old_price>p.price){{var pct=Math.round((1-p.price/p.old_price)*100);dh="<span class=\"price-old\">"+fP(p.old_price)+"</span><span class=\"price-discount\">"+pct+"% off</span>"}}return"<article class=\"product-card\"><a href=\"products/"+p.slug+".html\" class=\"product-card-link\"><div class=\"product-image\">"+bh+"<img src=\""+pI(p.image)+"\" alt=\""+p.name+"\" loading=\"lazy\"><div class=\"product-image-overlay\"><span class=\"view-details\">View Details \u2192</span></div></div><div class=\"product-info\"><span class=\"product-category\">"+p.category_name+"</span><h3 class=\"product-name\">"+p.name+"</h3><div class=\"product-rating\">"+st(p.rating)+"<span class=\"review-count\">("+p.reviews+")</span></div><div class=\"product-price\"><span class=\"price-current\">"+fP(p.price)+"</span>"+dh+"</div></div></a></article>"}}function go(){{var f=VF_PRODUCTS;if(p&&VF_CATMAP[p])f=f.filter(function(x){{return x.category_id==VF_CATMAP[p]}});var s=document.getElementById("sortSelect").value;if(s=="price-low")f.sort(function(a,b){{return a.price-b.price}});else if(s=="price-high")f.sort(function(a,b){{return b.price-a.price}});else if(s=="rating")f.sort(function(a,b){{return b.rating-a.rating}});else if(s=="name")f.sort(function(a,b){{return a.name.localeCompare(b.name)}});var g=document.getElementById("productGrid");g.innerHTML=f.map(function(p,i){{return"<div class=\"reveal reveal-delay-"+((i%4)+1)+"\">"+rc(p)+"</div>"}}).join("");document.querySelector(".products-count").textContent="Showing "+f.length+" products"}}document.getElementById("sortSelect").addEventListener("change",go);if(p)document.querySelectorAll(".filter-list a").forEach(function(a){{if(a.href.includes("category="+p))a.classList.add("active");else a.classList.remove("active")}});go();</script>'+footer())
print('Built products.html')

# Generate product pages
for p in DATA['products']:
    related=[r for r in DATA['products'] if r['category_id']==p['category_id'] and r['id']!=p['id']][:4]
    bh=f'<span class="badge badge-{p["badge"].lower()}">{e(p["badge"])}</span>' if p.get('badge') else ''
    dh=''
    if p.get('old_price') and p['old_price']>p['price']:
        dh=f'<span class="price-old">{fmt(p["old_price"])}</span><span class="price-discount">Save {fmt(p["old_price"]-p["price"])}</span>'
    fh=''.join(f'<li>{e(feat)}</li>' for feat in p['features'])
    th=''.join(f'<div class="product-thumb {"active" if i==0 else ""}" data-image="{ph_img(img,700,700)}"><img src="{ph_img(img,80,80)}" alt="{e(p["name"])}"></div>' for i,img in enumerate(p['images']))
    rh=''.join(f'<div class="reveal reveal-delay-{(i%4)+1}">{pcard(r)}</div>' for i,r in enumerate(related))
    with open(f'products/{p["slug"]}.html','w') as f:
        f.write(header(p['name']+' \u2014 Vikas Furnished',p['description'][:155],'products')+f'<div class="page-banner"><div class="container"><div class="breadcrumb"><a href="index.html">Home</a><span>/</span><a href="products.html">Products</a><span>/</span><span>{e(p["name"])}</span></div></div></div><div class="container"><div class="product-detail"><div class="product-gallery"><div class="product-main-image"><img id="mainProductImage" src="{ph_img(p["images"][0],700,700)}" alt="{e(p["name"])}"></div><div class="product-thumbs">{th}</div></div><div class="product-info-detail"><span class="product-category">{e(p["category_name"])}</span><h1>{e(p["name"])}</h1><div class="product-rating">{stars(p["rating"])}<span class="review-count">{p["rating"]} ({p["reviews"]} reviews)</span></div><div class="product-price-detail"><span class="price-current">{fmt(p["price"])}</span>{dh}</div>{"<div style=\"margin-bottom:1rem\">"+bh+"</div>" if p.get("badge") else ""}<p class="product-description">{e(p["description"])}</p><div class="product-features-list"><h3>Key Features</h3><ul>{fh}</ul></div><div class="product-actions"><div class="qty-selector"><button class="qty-btn" data-action="decrease">\u2212</button><input type="number" class="qty-input" value="1" min="1"><button class="qty-btn" data-action="increase">+</button></div><a href="contact.html" class="btn btn-primary btn-lg">Enquire Now</a><a href="contact.html" class="btn btn-outline btn-lg">Request a Quote</a></div><div class="product-meta"><div><strong>Category:</strong> {e(p["category_name"])}</div><div><strong>SKU:</strong> VF-{str(p["id"]).zfill(5)}</div><div><strong>Availability:</strong> <span style="color:var(--color-success)">In Stock</span></div><div><strong>Delivery:</strong> Free across India (7-14 days)</div></div></div></div></div>'+ (f'<section class="section section-cream"><div class="container"><div class="section-header"><span class="eyebrow">You May Also Like</span><h2 class="section-title">Related Products</h2></div><div class="product-grid">{rh}</div></div></section>' if related else '') +footer())
print(f'Built {len(DATA["products"])} product pages')

# Generate about.html, contact.html, privacy.html, terms.html
import datetime
with open('about.html','w') as f:
    f.write(header('About \u2014 Vikas Furnished','Our story.','about')+f'<div class="page-banner"><div class="container"><h1>About Vikas Furnished</h1><p>Crafting comfort, defining style.</p><div class="breadcrumb"><a href="index.html">Home</a><span>/</span><span>About</span></div></div></div><div class="container"><div class="about-hero"><div class="about-hero-text reveal"><span class="eyebrow">Our Story</span><h1>Furniture That Feels Like Home</h1><p>Vikas Furnished began with a simple belief that every home deserves beautiful, durable, thoughtfully designed furniture.</p><p>Our journey is rooted in deep respect for craftsmanship. Every piece passes through the hands of skilled artisans.</p><p>Today we offer a complete range of premium furniture built to last for generations.</p></div><div class="about-hero-visual reveal reveal-delay-1"></div></div></div><section class="section-tight section-cream"><div class="container"><div class="features-grid"><div class="feature-block reveal"><div class="feature-icon">\U0001f4c5</div><h3>15+ Years</h3><p>Of crafting premium furniture</p></div><div class="feature-block reveal reveal-delay-1"><div class="feature-icon">\U0001f3e0</div><h3>10,000+</h3><p>Homes furnished across India</p></div><div class="feature-block reveal reveal-delay-2"><div class="feature-icon">\U0001fab5</div><h3>500+</h3><p>Premium designs</p></div><div class="feature-block reveal reveal-delay-3"><div class="feature-icon">\u2b50</div><h3>4.7/5</h3><p>Average customer rating</p></div></div></div></section><section class="section"><div class="container"><div class="section-header reveal"><span class="eyebrow">What We Stand For</span><h2 class="section-title">Our Core Values</h2></div><div class="values-grid"><div class="value-card reveal"><div class="value-icon">\U0001f91d</div><h3>Craftsmanship</h3><p>We honour the art of furniture-making with precision and care.</p></div><div class="value-card reveal reveal-delay-1"><div class="value-icon">\U0001f33f</div><h3>Sustainability</h3><p>We source materials responsibly with eco-friendly finishes.</p></div><div class="value-card reveal reveal-delay-2"><div class="value-icon">\U0001f48e</div><h3>Quality First</h3><p>We never compromise on materials or construction.</p></div></div></div></section><section class="section section-cream"><div class="container"><div class="section-header reveal"><span class="eyebrow">Our Journey</span><h2 class="section-title">Milestones</h2></div><div class="timeline"><div class="timeline-item reveal"><div class="timeline-dot">1</div><div class="timeline-content"><h3>The Beginning</h3><p>Started as a small workshop in Bengaluru.</p></div></div><div class="timeline-item reveal reveal-delay-1"><div class="timeline-dot">2</div><div class="timeline-content"><h3>Going Online</h3><p>Launched our website for wider access.</p></div></div><div class="timeline-item reveal reveal-delay-2"><div class="timeline-dot">3</div><div class="timeline-content"><h3>Pan-India</h3><p>Expanded delivery across all major cities.</p></div></div><div class="timeline-item reveal reveal-delay-3"><div class="timeline-dot">4</div><div class="timeline-content"><h3>500+ Designs</h3><p>Furnished 10,000+ homes across India.</p></div></div></div></div></section><section class="cta-section"><div class="container"><h2>Visit Our Showroom or Shop Online</h2><a href="products.html" class="btn btn-gold btn-lg">Browse Products</a><a href="contact.html" class="btn btn-light btn-lg" style="margin-left:1rem">Find Our Showroom</a></div></section>'+footer())
with open('contact.html','w') as f:
    f.write(header('Contact \u2014 Vikas Furnished','Get in touch.','contact')+f'<div class="page-banner"><div class="container"><h1>Contact Us</h1><p>We\'d love to hear from you.</p><div class="breadcrumb"><a href="index.html">Home</a><span>/</span><span>Contact</span></div></div></div><div class="container"><div class="contact-layout"><div class="contact-info reveal"><span class="eyebrow">Get in Touch</span><h2>Lets Talk Furniture</h2><p style="color:var(--color-text-light);margin-bottom:2rem">Our team is ready to assist you.</p><div class="contact-detail"><div class="contact-detail-icon">\U0001f4cd</div><div><strong>Visit Our Showroom</strong><p>{e(SITE["address"])}</p></div></div><div class="contact-detail"><div class="contact-detail-icon">\U0001f4de</div><div><strong>Call Us</strong><p><a href="tel:+919876543210">{e(SITE["phone"])}</a></p></div></div><div class="contact-detail"><div class="contact-detail-icon">\u2709\ufe0f</div><div><strong>Email Us</strong><p><a href="mailto:{e(SITE["email"])}">{e(SITE["email"])}</a></p></div></div><div class="contact-detail"><div class="contact-detail-icon">\U0001f552</div><div><strong>Business Hours</strong><p>Mon-Sat: 10AM-8PM, Sun: 11AM-6PM</p></div></div><div class="contact-map"><p>Map: 123 Furniture Plaza, MG Road, Bengaluru</p></div></div><div class="contact-form-wrap reveal reveal-delay-1"><h2>Send Us a Message</h2><div id="formMessage"></div><form id="contactForm" onsubmit="return handleContact(event)"><div class="form-row"><div class="form-group"><label>Name *</label><input type="text" name="name" required></div><div class="form-group"><label>Email *</label><input type="email" name="email" required></div></div><div class="form-row"><div class="form-group"><label>Phone</label><input type="tel" name="phone"></div><div class="form-group"><label>Subject</label><select name="subject"><option value="">Select</option><option>Product Enquiry</option><option>Custom Order</option></select></div></div><div class="form-group"><label>Message *</label><textarea name="message" required></textarea></div><button type="submit" class="btn btn-primary btn-lg" style="width:100%">Send Message</button></form></div></div></div><script>function handleContact(e){{e.preventDefault();var m=document.getElementById("formMessage");m.className="form-message success";m.textContent="Thank you! Your message has been received.";document.getElementById("contactForm").reset();return false}}</script>'+footer())
